package io.github.codexpocket.app;
public final class AdbImportPolicyTest {
 static int tests;static void check(boolean value,String label){if(!value)throw new AssertionError(label);tests++;System.out.println("PASS "+label);}
 public static void main(String[] args){check(AdbImportPolicy.currentId("e0-abc",0),"first epoch accepted");check(!AdbImportPolicy.currentId("e0-abc",1),"reset rejects old request replay");check(AdbImportPolicy.currentId("e1-abc",1),"new epoch accepted");check(!AdbImportPolicy.currentId("e1-../abc",1),"epoch cannot weaken ID whitelist");check(AdbImportPolicy.sameContent("hash","hash"),"same payload deduplicated");check(!AdbImportPolicy.sameContent("hash","other"),"changed payload conflicts");check(AdbImportPolicy.recovery("queued",120001,true).equals("expired"),"old queued released without replay");check(AdbImportPolicy.recovery("processing",120001,true).equals("expired"),"old processing released without replay");check(AdbImportPolicy.recovery("processing",100,false).equals("delivery_unknown"),"interrupted UI delivery never replays");check(AdbImportPolicy.recovery("queued",100,false).isEmpty(),"unconsumed queue survives process restart");check(AdbImportPolicy.recovery("prepared",120001,false).isEmpty(),"prepared result stays terminal");System.out.println("PASS TOTAL "+tests);}
}
